// The move order the world mouse handler sends (0x44 bytes, vtable Addr::cOrder_vtable). Walk: target set, `follow`
// 1 makes the local hero walk straight at the cursor (0x4FB7E0 recomputes the target from the mouse every step, no
// path search, no cell snapping) as hold-to-walk does after half a second; 0 path-finds to the snapped target. Stop:
// all zero but `type`.
namespace Sacred::Order
{
    constexpr uintptr_t type = 0x04;         // 4: move
    constexpr uintptr_t mode = 0x14;         // 2: walk, 0: stop
    constexpr uintptr_t x = 0x18;            // world target
    constexpr uintptr_t y = 0x1C;
    constexpr uintptr_t follow = 0x20;
    constexpr size_t size = 0x44;
}

